head.script:
///////// 1. 변수 및 선언 영역 /////////
// 화면 리사이징

scwin.gIsurCd;

// 발행기관 조회처리 추가
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vSelObj;

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    await scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDATE.setValue(vCurDate.substring(0, 4) + "0101"); // 연초날짜
    edt_EDATE.setValue($c.ut.cGetToday2());

    // setObjectValue(rdo_MKT_ID, js_market);
    // js_market = "6"

};

/**
 * @method
 * @name readPrepayChg
 * @description read Prepay Chg 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readPrepayChg = async function() {
    // 선납잔액 조회
    url += "&SCREN_ID=" + "ULDINS21300.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
    const sbmOptions = {
        id : "sbm_dts_detail",
        action : "/PrepayInfoAction.do",
        ref : "",
        target : "dts_detail=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name readAllPrepayChg
 * @description 선납잔액전체 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readAllPrepayChg = async function() {
    const sbmOptions = {
        id : "sbm_dts_detail",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_detail=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listPrepayChg
 * @description 선납금 리스트 조회 - 입출금현황
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listPrepayChg = async function() {
    // var argv = fn_listPrepayChg.arguments;
    // var argc = fn_listPrepayChg.arguments.length;
    // vPAGENO = (argc == 0) ? 0 : vPAGENO = argv[0];

    url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
    url += "&SDATE=" + edt_SDATE.getValue();
    url += "&EDATE=" + edt_EDATE.getValue();
    url += "&SCREN_ID=" + "ULDINS21300.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    // alert(url);
    const sbmOptions = {
        id : "sbm_dts_PassList",
        action : "/PrepayInfoAction.do",
        ref : "",
        target : "dts_PassList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listBalanceByIsurCd
 * @description 회사별잔고현황
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listBalanceByIsurCd = async function() {
    const sbmOptions = {
        id : "sbm_dts_PassList2",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_PassList2=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};
scwin.arrPar = new Array();

/**
 * @method
 * @name getParam
 * @description 전달값을 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue(); // 발행기관코드
    scwin.arrPar[1] = txb_param2.getValue(); // 발행기관코드명

    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    scwin.arrPar, length;
};

/**
 * @method
 * @name popupPrepayChg
 * @description 발행기관별 선납금을 조회한다.
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.popupPrepayChg = async function(row, colid) {
    if (colid === "COM_NM") {
        const vISUR_CD = dts_PassList.getCellData(row, "ISUR_CD"); // ISUR_CD
        const options = {
            id: "ULDINS21301",
            title: "선납금 조회",
            type: "browserPopup",
            width: "820px",
            height: "580px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/etc/ULDINS21301.gfm", options);
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    await scwin.popupPrepayChg(row, colid);
};

/**
 * @method
 * @name btn_New_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_New_onclick = async function() {
    const options = {
        id: "ULDINS21302",
        title: "선납금 등록",
        type: "browserPopup",
        width: "820px",
        height: "690px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/etc/ULDINS21302.gfm", options);
};

/**
 * @method
 * @name btn_SDATE_onclick
 * @description btn_SDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDATE_onclick = function() {
    popUpCalendar2(edt_SDATE);
};

/**
 * @method
 * @name btn_EDATE_onclick
 * @description btn_EDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_EDATE_onclick = function() {
    popUpCalendar2(edt_EDATE);
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    scwin.init();
    const vTp = cmb_PeriodTp.getValue();
    if (vTp === 7) {
        // 전체
        edt_SDATE.setValue('00010101');
        edt_EDATE.setValue('99991231');
    } else {
        $c.stf.setFromToDate(vTp, edt_SDATE, edt_EDATE);
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave("ULDINS21300.xml", SCREN_PROCS_TP_CD_07, '');
    if (tab_IsurInfo.getSelectedTabIndex() === "1") {
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "입출금현황", type: "8"});
    } else if (tab_IsurInfo.getSelectedTabIndex() === "2") {
        $c.data.downloadGridViewExcel(grd_Grid2, {fileName: "회사별잔고현황", type: "8"});
    }
};

/**
 * @method
 * @name dts_PassList_OnLoadCompleted
 * @description dts_PassList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_PassList_OnLoadCompleted = async function(rowcount) {
    if (dts_PassList.errorMsg) {
        await $c.win.alert(dts_PassList.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    if (txb_ISUR_CD.getValue() === "") {
        await scwin.readAllPrepayChg(); // 발행기관 전체 총선납액,잔액 조회

    } else {
        await scwin.readPrepayChg(); // 발행기관별 조회 시 총선납액,잔액 조회

    }

};

/**
 * @method
 * @name dts_PassList2_OnLoadCompleted
 * @description dts_PassList2 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_PassList2_OnLoadCompleted = async function(rowcount) {
    if (dts_PassList2.errorMsg) {
        await $c.win.alert(dts_PassList2.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    if (txb_ISUR_CD.getValue() === "") {
        await scwin.readAllPrepayChg(); // 발행기관 전체 총선납액,잔액 조회

    } else {
        await scwin.readPrepayChg(); // 발행기관별 조회 시 총선납액,잔액 조회

    }

};

/**
 * @method
 * @name dts_PassList_OnLoadError
 * @description dts_PassList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_PassList_OnLoadError = async function() {
    await $c.win.alert(dts_PassList);
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw !== "" && foColum === "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

        else return false;
    } else {
        return true;
    }
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    txb_param1.hide();
    txb_param2.hide();
    txb_COM_NM2.hide();
    $c.cm.PanelToGroupBox(panel_1);
    scwin.init();
    await scwin.listPrepayChg();
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    if (tab_IsurInfo.getSelectedTabIndex() === "1") {
        await scwin.listPrepayChg();
    } else if (tab_IsurInfo.getSelectedTabIndex() === "2") {
        await scwin.listBalanceByIsurCd();
    }
};

/**
 * @method
 * @name img_SRCH_ISUR_CD_onclick
 * @description img_SRCH_ISUR_CD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_SRCH_ISUR_CD_onclick = function() {
    ins_popupOpen(txb_ISUR_CD, txb_SRCH_ISUR_NM, "ULDINS90400", "발행기관 코드", "460", "430");
};

/**
 * @method
 * @name img_SRCH_ISUR_CD2_onclick
 * @description img_SRCH_ISUR_CD2 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_SRCH_ISUR_CD2_onclick = function() {
    txb_ISUR_CD.setValue("");
    txb_SRCH_ISUR_NM.setValue("");
    txb_TOT_PREPAY_AMT.setValue("");
    txb_PREPAY_BAL.setValue("");
};

/**
 * @method
 * @name dts_detail_OnLoadError
 * @description dts_detail 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_detail_OnLoadError = async function() {
    await $c.win.alert(dts_detail);
};

/**
 * @method
 * @name tab_IsurInfo_OnSelChanged
 * @description tab Isur Info On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tab_IsurInfo_OnSelChanged = async function(nIndex) {
    if (nIndex === "1") {
        btn_New.show("");
        await scwin.listPrepayChg();
    } else if (nIndex === "2") {
        btn_New.hide();
        await scwin.listBalanceByIsurCd();
    }
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};
